PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

.visible .entry reduce_sum_fp16(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 dim1,
    .param .u32 dim2
)
{
    // ----------------------------------------------------
    // Register declarations
    // ----------------------------------------------------
    .reg .pred   %p;
    .reg .u64    %in_ptr, %out_ptr;
    .reg .u32    %batch, %dim1, %dim2;
    .reg .u32    %tid, %blockIdx_x, %blockDim_x;
    .reg .u32    %total;
    .reg .u32    %bidx, %d2idx;
    .reg .u64    %offset_in, %offset_out, %addr;
    .reg .u32    %tmp, %j;
    .reg .f16    %val_f16;
    .reg .f32    %val_f32, %acc_f32;

    // ----------------------------------------------------
    // Load kernel parameters
    // ----------------------------------------------------
    ld.param.u64    %in_ptr,   [input_ptr];
    ld.param.u64    %out_ptr,  [output_ptr];
    ld.param.u32    %batch,    [batch];
    ld.param.u32    %dim1,     [dim1];
    ld.param.u32    %dim2,     [dim2];

    // ----------------------------------------------------
    // Compute global thread id
    // ----------------------------------------------------
    mov.u32 %tid.x,        %tid.x;          // threadIdx.x
    mov.u32 %blockIdx_x,   %ctaid.x;        // blockIdx.x
    mov.u32 %blockDim_x,   %ntid.x;         // blockDim.x
    mad.lo.u32 %tid, %blockIdx_x, %blockDim_x, %tid.x; // tid = blockIdx.x * blockDim.x + threadIdx.x

    // total = batch * dim2
    mul.lo.u32 %total, %batch, %dim2;
    setp.ge.u32 %p, %tid, %total;
    @%p ret;

    // ----------------------------------------------------
    // Compute (batch, dim2) coordinates for this thread
    // ----------------------------------------------------
    div.u32    %bidx, %tid, %dim2;               // batch index
    mul.lo.u32 %tmp, %bidx, %dim2;
    sub.u32    %d2idx, %tid, %tmp;               // dim2 index

    // ----------------------------------------------------
    // Compute input base offset: (bidx * dim1 * dim2) + d2idx
    // ----------------------------------------------------
    mul.lo.u32 %tmp, %bidx, %dim1;               // bidx * dim1
    mul.lo.u32 %tmp, %tmp, %dim2;                // * dim2
    add.u32    %tmp, %tmp, %d2idx;               // + d2idx
    cvt.u64.u32 %offset_in, %tmp;
    mul.lo.u64 %offset_in, %offset_in, 2;        // sizeof(half) = 2 bytes

    // ----------------------------------------------------
    // Compute output offset: (bidx * dim2) + d2idx
    // ----------------------------------------------------
    mul.lo.u32 %tmp, %bidx, %dim2;
    add.u32    %tmp, %tmp, %d2idx;
    cvt.u64.u32 %offset_out, %tmp;
    mul.lo.u64 %offset_out, %offset_out, 2;

    // ----------------------------------------------------
    // Initialize accumulator (fp32)
    // ----------------------------------------------------
    mov.f32 %acc_f32, 0f00000000;   // 0.0f

    // ----------------------------------------------------
    // Loop over reduction dimension (dim1)
    // ----------------------------------------------------
    mov.u32 %j, 0;
$loop:
    // address = offset_in + j * dim2 * sizeof(half)
    mul.lo.u32 %tmp, %j, %dim2;
    cvt.u64.u32 %addr, %tmp;
    mul.lo.u64 %addr, %addr, 2;
    add.u64 %addr, %offset_in, %addr;

    ld.global.f16 %val_f16, [%in_ptr + %addr];
    cvt.f32.f16 %val_f32, %val_f16;
    fadd.rn.f32 %acc_f32, %acc_f32, %val_f32;

    add.u32 %j, %j, 1;
    setp.lt.u32 %p, %j, %dim1;
    @%p bra $loop;

    // ----------------------------------------------------
    // Write result (convert back to fp16)
    // ----------------------------------------------------
    cvt.rn.f16.f32 %val_f16, %acc_f32;
    st.global.f16 [%out_ptr + %offset_out], %val_f16;

    ret;
}
'''

import torch
import torch.nn as nn
from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch, dim1, dim2 = x.shape
        out = torch.empty(batch, 1, dim2, dtype=torch.float16, device=x.device)

        block = (256,)
        grid = ((batch * dim2 + 255) // 256,)

        args = [x.data_ptr(), out.data_ptr(), batch, dim1, dim2]
        ptx_launch(self.module, "reduce_sum_fp16", grid, block, args)

        return out
